Definition Wc : list L5.range := [(Rr, 320); (IS, 272); (E, 16); (ch, 16384); (0xdb5c0, 2); (0xfd058, 544)].
Lemma hfacts : forall M model cr ps eg, hi_heap HI (PML.ps_blocks ps ++ LBo ++ PMES.g_lbv eg) cr M (m_vmmaps model) ->
  (forall b, In b (PML.ps_blocks ps ++ LBo ++ PMES.g_lbv eg) -> fst b <> ch -> PML.apart (fst b) (snd b) ch 16384) /\
