(* [comment removed for export] *)
Lemma ginv_chunk : forall M M' model cr ps gp rdst bof gp' rdst' code' bof' g' B eg spc,
  ginv M model cr ps gp rdst 0 bof g0 B eg -> PMS.win_exhausted ps ->
  L5.frame_but ((spc - 512, 512) :: Wc) M M' -> mem_grows M M' -> sp - SS <= spc - 512 -> spc <= sp ->
