Definition We : list L5.range := [(E, 16); (0xdb5c0, 2); (0xfd058, 544)].
Lemma ginv_setec : forall M M' model cr ps gp rdst bof B eg spc code',
  ginv M model cr ps gp rdst 0 bof g0 B eg -> L5.frame_but ((spc - 256, 256) :: We) M M' -> mem_grows M M' -> sp - SS <= spc - 256 -> spc <= sp ->
