(* [comment removed for export] *)
Definition ginv0 (M : mem) (model : Model) (LBh : list (Z * Z)) (cr : credit) (gp rdst : Z) (bof : bool) (eg : PMES.eghost) : Prop :=
  TPS.rdr_at M Rr IS V ch bof /\ PML.isrc_at M IS rep gp rdst /\ PML.vis_at M V /\ hi_heap HI LBh cr M (m_vmmaps model) /\ (forall b, In b (LBo ++ PMES.g_lbv eg) -> In b LBh) /\
  PML.model_ok model /\ model_but_vm model0 model /\ TK2.FR L LBk sp SS foot M0 M /\ (forall a, 0 <= a < 2 ^ 64 -> foot a -> M0 (Z_to_bv 64 a) <> None -> M (Z_to_bv 64 a) <> None) /\
  PMES.enc_inv M V S2 eg /\ PML.lits_ok M.

(* [comment removed for export] *)
Lemma ginv0_entry : forall M M' model cr ps gp rdst code bof g B eg lo hi,
